```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Units: mm. Print orientation: flat on bed, top face up.

$fn = 128;

// --- Ring dimensions ---
outer_d   = 50;   // outer diameter
inner_d   = 34;   // inner (bore) diameter
thickness = 5;    // ring thickness (Z)

// --- Tick mark dimensions ---
tick_count  = 12;   // number of evenly spaced ticks
tick_width  = 1.5;  // groove width (tangential)
tick_depth  = 1;    // groove depth into top face
tick_length = 4;    // radial length inward from outer edge

// --- Clearances for clean boolean cuts ---
eps   = 0.01;  // small overlap
over  = 0.5;   // extension past outer edge / top face

outer_r = outer_d / 2;
inner_r = inner_d / 2;

difference() {
    // Annulus body
    difference() {
        cylinder(h = thickness, r = outer_r);
        translate([0, 0, -over])
            cylinder(h = thickness + 2 * over, r = inner_r);
    }

    // Radial tick grooves, first on +X axis
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, i * 360 / tick_count])
            translate([outer_r - tick_length,
                       -tick_width / 2,
                       thickness - tick_depth])
                cube([tick_length + over,
                      tick_width,
                      tick_depth + over]);
    }
}
