// Anti-vibration foot for a benchtop instrument
// Print orientation: wide base on the bed (z = 0), narrow top at z = 15

// ---------- Dimensions (mm) ----------
base_d        = 50;    // frustum diameter at the bottom (z = 0)
top_d         = 42;    // frustum diameter at the flat top
foot_h        = 15;    // overall height of the foot
recess_d      = 44;    // rubber-pad recess diameter in the bottom face
recess_depth  = 3;     // rubber-pad recess depth
screw_d       = 4.5;   // central through-hole diameter for the screw
eps           = 0.5;   // overshoot for clean boolean cuts

$fn = 128;             // smoothness of curved surfaces

// ---------- Model ----------
difference() {
    // Frustum body
    cylinder(h = foot_h, d1 = base_d, d2 = top_d);

    // Rubber-pad recess cut into the bottom face
    translate([0, 0, -eps])
        cylinder(h = recess_depth + eps, d = recess_d);

    // Central screw hole, through along the Z axis
    translate([0, 0, -eps])
        cylinder(h = foot_h + 2 * eps, d = screw_d);
}
