```openscad
// Stiffened cover panel
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---- Plate ----
plate_len   = 80;   // plate length along X (mm)
plate_wid   = 50;   // plate width along Y (mm)
plate_thk   = 2;    // plate thickness (z = 0 to 2)

// ---- Ribs ----
rib_count   = 3;    // number of stiffening ribs
rib_thk     = 2;    // rib thickness along X (mm)
rib_height  = 4;    // rib height above plate (z = 2 to 6)
rib_pitch   = plate_len / (rib_count + 1);  // 20 mm centre-to-centre spacing
rib_overlap = 0.01; // small overlap into plate for a clean union

union() {
    // Base plate, centred in X and Y, sitting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y, centres at x = -20, 0, 20
    for (i = [1 : rib_count]) {
        x_c = -plate_len/2 + i * rib_pitch;
        translate([x_c - rib_thk/2, -plate_wid/2, plate_thk - rib_overlap])
            cube([rib_thk, plate_wid, rib_height + rib_overlap]);
    }
}
