// Pin hinge leaf - one leaf with two outer knuckles
$fn = 64;

// Plate
plate_len   = 45;    // X length of plate
plate_wid   = 30;    // Y width of plate
plate_thk   = 2.5;   // plate thickness (Z)

// Knuckles
