// Star-shaped indexing wheel
// Flat 5-pointed star plate with a central through-hole

// ---------------- Parameters ----------------
n_points      = 5;    // number of star points
outer_r       = 30;   // radius of outer (tip) points from centre [mm]
inner_r       = 15;   // radius of inner (valley) points from centre [mm]
plate_t       = 3;    // plate thickness [mm]
hole_d        = 8;    // central through-hole diameter [mm]
start_angle   = 0;    // angle of first outer point (+X axis) [deg]
cut_extra     = 0.5;  // extra length on cutting shapes past faces [mm]
$fn           = 96;   // facet count for curved shapes

// ---------------- Derived ----------------
step = 360 / (2 * n_points);  // angular spacing between consecutive vertices

// Star outline: alternating outer and inner vertices
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (r = (i % 2 == 0) ? outer_r : inner_r,
             a = start_angle + i * step)
        [r * cos(a), r * sin(a)]
];

// ---------------- Model ----------------
difference() {
    // Star plate
    linear_extrude(height = plate_t)
        polygon(points = star_pts);

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_t + 2 * cut_extra, $fn = $fn);
}
