// ---------- Pocket ----------
module pocket() {
    translate([0, 0, block_height - pocket_depth])
        linear_extrude(height = pocket_depth + cut_extra)
            square([pocket_size, pocket_size], center = true);
}

// ---------- Part ----------
difference() {
    frustum();
    pocket();
