axle_d         = 5;    // axle hole diameter
spoke_count    = 4;    // number of spokes
spoke_width    = 4;    // spoke width
spoke_overlap  = 0.5;  // spoke extends this far into hub and rim for solid union
eps            = 0.5;  // cut overshoot past faces

