// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, centred on origin, building +Z

$fn = 128;

// ---- Dimensions (mm) ----
wheel_thickness = 8;     // overall thickness of the part (Z)
rim_outer_d     = 100;   // outer diameter of rim
rim_width       = 4;     // radial width of rim ring
hub_d           = 16;    // hub outer diameter
axle_d          = 8;     // axle hole diameter
spoke_count     = 6;     // number of spokes
spoke_width     = 4;     // width of each spoke
first_spoke_ang = 0;     // first spoke along +X

eps = 0.5;               // cutter overshoot

// ---- Derived ----
rim_outer_r = rim_outer_d / 2;
rim_inner_r = rim_outer_r - rim_width;
hub_r       = hub_d / 2;
// spokes overlap into hub and rim to ensure a solid union
spoke_start = hub_r - 1;
spoke_end   = rim_inner_r + 1;

module rim() {
    difference() {
        cylinder(h = wheel_thickness, r = rim_outer_r);
        translate([0, 0, -eps])
            cylinder(h = wheel_thickness + 2 * eps, r = rim_inner_r);
    }
}

module hub() {
    cylinder(h = wheel_thickness, r = hub_r);
}

module spokes() {
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, first_spoke_ang + i * 360 / spoke_count])
            translate([spoke_start, -spoke_width / 2, 0])
                cube([spoke_end - spoke_start, spoke_width, wheel_thickness]);
}

difference() {
    union() {
        rim();
        hub();
        spokes();
    }
    // axle hole through the hub
    translate([0, 0, -eps])
        cylinder(h = wheel_thickness + 2 * eps, r = axle_d / 2);
}
