rim_od         = 80;   // rim outer diameter
rim_width      = 5;    // radial width of rim ring
hub_d          = 14;   // hub outer diameter
axle_d         = 8;    // axle hole diameter
spoke_count    = 8;    // number of spokes
spoke_width    = 4;    // spoke width
spoke_start_angle = 0; // first spoke along +X

eps            = 0.5;  // cutter overshoot past faces
$fn            = 128;  // circle resolution

// ---------------- Derived ----------------
rim_or = rim_od / 2;
rim_ir = rim_or - rim_width;
hub_r  = hub_d / 2;
axle_r = axle_d / 2;

// Spokes run from hub centre region to just inside the rim, overlapping both
spoke_inner = hub_r - 1;          // overlap into hub
spoke_outer = rim_ir + 1;         // overlap into rim
spoke_len   = spoke_outer - spoke_inner;

// ---------------- Model ----------------
difference() {
    union() {
        // Outer rim ring
        difference() {
            cylinder(r = rim_or, h = thickness);
            translate([0, 0, -eps])
                cylinder(r = rim_ir, h = thickness + 2 * eps);
        }

        // Hub
        cylinder(r = hub_r, h = thickness);

        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start_angle + i * 360 / spoke_count])
                translate([spoke_inner, -spoke_width / 2, 0])
                    cube([spoke_len, spoke_width, thickness]);
    }

    // Axle hole through hub
    translate([0, 0, -eps])
        cylinder(r = axle_r, h = thickness + 2 * eps);
}
