// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, centred on origin

$fn = 128;

// --- Dimensions (mm) ---
thickness      = 5;    // overall part thickness (Z)
rim_od         = 80;   // rim outer diameter
rim_width      = 6;    // rim radial width
hub_d          = 20;   // hub outer diameter
axle_d         = 8;    // axle hole diameter
spoke_count    = 4;    // number of spokes
spoke_width    = 5;    // spoke width
spoke_angle0   = 0;    // first spoke along +X

// --- Derived ---
rim_id     = rim_od - 2 * rim_width;   // rim inner diameter
overlap    = 1;                        // spoke overlap into hub/rim
eps        = 0.5;                      // cut extension past faces

spoke_start = hub_d / 2 - overlap;     // radial start of spoke
spoke_end   = rim_id / 2 + overlap;    // radial end of spoke
spoke_len   = spoke_end - spoke_start;

difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(d = rim_od, h = thickness);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = thickness + 2 * eps);
        }

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_angle0 + i * 360 / spoke_count])
                translate([spoke_start, -spoke_width / 2, 0])
                    cube([spoke_len, spoke_width, thickness]);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
